package com.termux.app.workspace;
import android.os.*;
import android.widget.*;
import android.view.Gravity;
import com.termux.app.TermuxActivity;
import org.json.*;
import java.util.concurrent.*;
import java.util.function.*;

/** Claude-only local status and native model/mode controls; no remote quota estimate. */
final class ClaudeLiveUi {
 interface Applied {void save(WorkspaceStore.Session p,String run,String model,String mode);}
 private final TermuxActivity activity;private final Supplier<WorkspaceStore.Session> current;private final BooleanSupplier visible;private final Applied applied;
 private final Handler handler=new Handler(Looper.getMainLooper());private final ExecutorService reader=Executors.newSingleThreadExecutor(),actions=Executors.newSingleThreadExecutor();
 private BiConsumer<WorkspaceStore.Session,String> effortApplied=(p,v)->{};
 void effortApplied(BiConsumer<WorkspaceStore.Session,String> save){effortApplied=save;}
 private Runnable chatPreview=()->{},chatSave=()->{};
 void chatPresentation(Runnable preview,Runnable save){chatPreview=preview;chatSave=save;}
 private boolean closed,loading;private String run="";private JSONObject status;private TextView chip,detailsModel,detailsMode,detailsEffort,detailsInfo;private android.app.AlertDialog detailsDialog;private String detailsRun="";
 ClaudeLiveUi(TermuxActivity a,Supplier<WorkspaceStore.Session> c,BooleanSupplier v,Applied save){activity=a;current=c;visible=v;applied=save;handler.post(poll);}
 private String tr(String ru,String en){return WorkspaceLanguage.code(activity).equals("ru")?ru:en;}
 private final Runnable poll=new Runnable(){public void run(){if(closed)return;WorkspaceStore.Session p=current.get();if(p!=null&&visible.getAsBoolean())load(p);handler.postDelayed(this,1500);}};
 private boolean owns(String r){WorkspaceStore.Session p=current.get();return !closed&&p!=null&&r.equals(p.claudeSocketId);}
 void render(LinearLayout parent,WorkspaceStore.Session p){if(!run.equals(p.claudeSocketId)){run=p.claudeSocketId;status=null;}chip=AgentStatusUi.chip(activity,"",tr("Статус, модель и права Claude","Claude status, model and permissions"),()->menu(p));AgentStatusUi.attach(parent,chip);update();load(p);}
 private String mode(String value){return value.equals("plan")?tr("План / чтение","Plan / read"):value.equals("acceptEdits")?tr("Разрешать правки","Accept edits"):tr("Подтверждать действия","Confirm actions");}
 private String state(){if(status==null)return tr("подключение…","connecting…");if(!status.optBoolean("ready"))return tr("терминал / вход","terminal / sign-in");switch(status.optString("state")){case "idle":return tr("готов","ready");case "responding":return tr("отвечает","responding");case "waiting_for_confirmation":return tr("ожидает подтверждения","awaiting confirmation");default:return tr("проверка состояния","checking status");}}
 private String model(WorkspaceStore.Session p){return status==null?(p.claudeModel.isEmpty()?tr("По умолчанию","Default"):p.claudeModel):status.optString("model",tr("Нет данных","Unavailable"));}
 private boolean canControl(){return status!=null&&status.optBoolean("ready")&&status.optString("state").equals("idle")&&status.optBoolean("canChange",true);}
 private String usage(){JSONObject value=status==null?null:status.optJSONObject("usage");String body=tr("Расход последнего запроса. Остаток лимитов подписки этим каналом не предоставляется.","Usage for the last request. Remaining subscription limits are not supplied by this channel.");if(value!=null&&value.has("input")&&value.has("output"))body+="\n\n"+tr("Входные токены: ","Input tokens: ")+value.optLong("input")+"\n"+tr("Выходные токены: ","Output tokens: ")+value.optLong("output");else body+="\n"+tr("Данных о расходе пока нет.","No usage data yet.");return body;}
 private void update(){if(chip==null)return;WorkspaceStore.Session p=current.get();if(p==null||!owns(run))return;String rights=mode(status==null?p.claudeMode:status.optString("mode"));String label="Claude · "+model(p)+"\n"+state()+" · "+rights+" ›";if(!label.contentEquals(chip.getText()))chip.setText(label);
  if(detailsDialog!=null&&detailsDialog.isShowing()){if(!owns(detailsRun)){detailsDialog.dismiss();return;}detailsModel.setText(tr("Модель: ","Model: ")+model(p)+" ›");detailsMode.setText(tr("Режим прав: ","Permissions: ")+rights+" ›");AgentStatusUi.available(detailsModel,canControl());AgentStatusUi.available(detailsMode,canControl());detailsEffort.setText(tr("Рассуждения: ","Reasoning: ")+AgentStatusUi.level(activity,status==null?"":status.optString("effort"))+" ›");AgentStatusUi.available(detailsEffort,canControl()&&effortOptions().length()>0);detailsInfo.setText(tr("Состояние: ","State: ")+state()+"\n\n"+usage()+(canControl()?"":"\n\n"+tr("Выбор доступен после подключения и завершения текущего действия Claude.","Selection is available after connecting and when Claude finishes its current action.")));}
 }
 private void load(WorkspaceStore.Session p){if(closed||loading)return;loading=true;String captured=p.claudeSocketId;reader.execute(()->{JSONObject r=null;try{r=ClaudeLiveControl.request(activity.getFilesDir(),captured,AgentChatUi.op("status"));}catch(Exception ignored){}JSONObject value=r;handler.post(()->{loading=false;if(owns(captured)){status=value;update();}});});}
 private void menu(WorkspaceStore.Session p){String captured=p.claudeSocketId;if(!owns(captured))return;if(detailsDialog!=null)detailsDialog.dismiss();LinearLayout body=AgentStatusUi.body(activity);detailsModel=AgentStatusUi.row(body,"","model",()->{if(owns(captured))models(p);});detailsMode=AgentStatusUi.row(body,"","permissions",()->{if(owns(captured))modes(p);});detailsEffort=AgentStatusUi.row(body,"","reasoning",()->{if(owns(captured))efforts(p);});detailsInfo=AgentStatusUi.info(body,"");detailsInfo.setId(android.R.id.message);detailsRun=captured;
  AgentChatScale.controls(body,p,()->owns(captured),chatPreview,chatSave);
  android.app.AlertDialog dialog=WorkspaceDialogs.builder(activity).setTitle(tr("Статус Claude","Claude status")).setView(AgentStatusUi.scroll(body)).setPositiveButton(tr("Обновить","Refresh"),null).setNegativeButton(tr("Закрыть","Close"),null).create();detailsDialog=dialog;dialog.setOnDismissListener(d->{if(detailsDialog==dialog)detailsDialog=null;});dialog.setOnShowListener(d->dialog.getButton(android.app.AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(owns(captured))load(p);}));dialog.show();update();
 }
 private void models(WorkspaceStore.Session p){if(!canControl())return;String captured=p.claudeSocketId;reader.execute(()->{JSONObject r=null;try{r=ClaudeLiveControl.request(activity.getFilesDir(),captured,AgentChatUi.op("models"));}catch(Exception ignored){}JSONObject result=r;handler.post(()->{if(!owns(captured))return;JSONArray models=result==null?null:result.optJSONArray("models");if(models==null||models.length()==0){failure();return;}String[] labels=new String[models.length()],values=new String[models.length()];for(int i=0;i<models.length();i++){JSONObject m=models.optJSONObject(i);labels[i]=m.optString("label");values[i]=m.optString("value").equals("default")?"":m.optString("value");}int checked=-1;for(int i=0;i<values.length;i++)if(status!=null&&(values[i].isEmpty()?"default":values[i]).equals(status.optString("selectedModel",status.optString("model"))))checked=i;WorkspaceDialogs.builder(activity).setTitle(tr("Модель Claude","Claude model")).setSingleChoiceItems(labels,checked,(d,w)->{if(!owns(captured))return;d.dismiss();confirm(p,"set-model","model",values[w],labels[w]);}).setNegativeButton(tr("Назад","Back"),null).show();});});}
 private JSONArray effortOptions(){JSONArray out=new JSONArray(),values=status==null?null:status.optJSONArray("effortOptions");if(values!=null)for(int i=0;i<values.length();i++){String v=values.optString(i);if(java.util.Arrays.asList("default","low","medium","high","xhigh","max").contains(v))out.put(v);}return out;}
 private void efforts(WorkspaceStore.Session p){if(!canControl())return;JSONArray values=effortOptions();if(values.length()==0)return;String captured=p.claudeSocketId,selected=status.optString("selectedModel"),before=p.claudeEffort;String[] labels=new String[values.length()];int checked=-1;for(int i=0;i<labels.length;i++){labels[i]=AgentStatusUi.level(activity,values.optString(i));if(values.optString(i).equals(status.optString("effort")))checked=i;}WorkspaceDialogs.builder(activity).setTitle(tr("Рассуждения Claude","Claude reasoning")).setSingleChoiceItems(labels,checked,(d,w)->{d.dismiss();String value=values.optString(w);WorkspaceDialogs.builder(activity).setTitle(tr("Подтвердить выбор","Confirm selection")).setMessage(labels[w]+"\n\n"+tr("Уровень штатного effort Claude. Применяется к следующим запросам; расход и время ответа могут измениться. Права не меняются.","Native Claude effort level. Applies to subsequent requests; usage and response time may change. Permissions stay the same.")).setPositiveButton(tr("Применить","Apply"),(confirm,index)->{if(!owns(captured)||!canControl())return;actions.execute(()->{boolean ok=false;try{JSONObject r=ClaudeLiveControl.request(activity.getFilesDir(),captured,new JSONObject().put("op","set-effort").put("model",selected).put("effort",value));ok=r.optBoolean("ok")&&value.equals(r.optString("effort"));}catch(Exception ignored){}boolean accepted=ok;handler.post(()->{if(closed||!captured.equals(p.claudeSocketId))return;if(accepted&&before.equals(p.claudeEffort))effortApplied.accept(p,value);if(owns(captured)){if(!accepted)failure();load(p);}});});}).setNegativeButton(tr("Назад","Back"),null).show();}).setNegativeButton(tr("Назад","Back"),null).show();}
 private void modes(WorkspaceStore.Session p){if(!canControl())return;String captured=p.claudeSocketId;String[] codes={"manual","acceptEdits","plan"};String[] labels={mode(codes[0])+tr(" — запрашивать разрешения на действия"," — ask before actions"),mode(codes[1])+tr(" — правки файлов без отдельного запроса; команды по правилам Claude"," — approve file edits; commands follow Claude policy"),mode(codes[2])+tr(" — анализ и планирование по штатным правилам Claude"," — analysis and planning under Claude policy")};int checked=java.util.Arrays.asList(codes).indexOf(status.optString("mode"));WorkspaceDialogs.builder(activity).setTitle(tr("Режим прав Claude","Claude permissions")).setSingleChoiceItems(labels,checked,(d,w)->{if(!owns(captured))return;d.dismiss();confirm(p,"set-mode","mode",codes[w],labels[w]);}).setNegativeButton(tr("Назад","Back"),null).show();}
 private void confirm(WorkspaceStore.Session p,String op,String field,String value,String label){String captured=p.claudeSocketId;WorkspaceDialogs.builder(activity).setTitle(tr("Подтвердить выбор","Confirm selection")).setMessage(label).setPositiveButton(tr("Применить","Apply"),(d,w)->{if(owns(captured))apply(p,op,field,value);}).setNegativeButton(tr("Назад","Back"),null).show();}
 private void apply(WorkspaceStore.Session p,String op,String field,String value){if(!owns(p.claudeSocketId)||!canControl())return;String captured=p.claudeSocketId;JSONObject q=AgentChatUi.op(op);try{q.put(field,value);}catch(JSONException impossible){throw new IllegalStateException(impossible);}actions.execute(()->{boolean ok=false;try{ok=ClaudeLiveControl.request(activity.getFilesDir(),captured,q).optBoolean("ok");}catch(Exception ignored){}boolean accepted=ok;handler.post(()->{if(closed||!captured.equals(p.claudeSocketId))return;if(accepted){applied.save(p,captured,field.equals("model")?value:p.claudeModel,field.equals("mode")?value:p.claudeMode);if(owns(captured))load(p);}else if(owns(captured))failure();});});}
 private void failure(){WorkspaceDialogs.builder(activity).setTitle("Claude").setMessage(tr("Claude пока не подтвердил действие. Дождитесь окончания ответа или откройте терминал кнопкой робота и проверьте вход. Для старой сессии потребуется новый запуск.","Claude has not confirmed the action. Wait for the reply to finish or check sign-in using the robot terminal. An older session needs a new launch.")).setPositiveButton(tr("Назад","Back"),null).show();}
 void close(){closed=true;if(detailsDialog!=null)detailsDialog.dismiss();handler.removeCallbacks(poll);reader.shutdownNow();actions.shutdown();}
}
